# Surah Al-An'am (chapter 6) — part 16 (final): ayat 155-165 (IDs 944-954)
SURAH = 6

ENTRIES = {
944: (
"اور یہ — ایک کتاب ہے — ہم — نے نازل کی — مبارک — پس — اس — کی پیروی کرو — اور ڈرو — شاید کہ تم پر رحم کیا جائے",
"""۱۔ قرآن — مبارک — پیروی کی — کتاب۔
۲۔ ’’وَهَٰذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ‘‘ — اور یہ — ایک کتاب ہے — ہم — نے نازل کی — مبارک — پس — اس — کی پیروی کرو — اور ڈرو — شاید کہ تم پر رحم کیا جائے — یعنی قرآن کی پیروی — اور تقویٰ — رحمت — کی کنڈی ہے۔
۳۔ عملی سبق: قرآن کی پیروی کرو؛ تقویٰ اپناؤ؛ اللہ کی رحمت کی امید رکھو۔"""
),
945: (
"(ایسا ہو) تاکہ تم یہ نہ کہو — کتاب — صرف — دو — جماعتوں — پر — ہم سے پہلے — نازل کی گئی — اور بے شک — ہم — ان — کی — پڑھائی سے — غافل — رہے",
"""۱۔ حجت — تم پر بھی پوری ہو چکی ہے۔
۲۔ ’’أَن تَقُولُوا إِنَّمَا أُنزِلَ الْكِتَابُ عَلَىٰ طَائِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَافِلِينَ‘‘ — (ایسا ہو) تاکہ تم یہ نہ کہو — کتاب — صرف — دو — جماعتوں — پر — ہم سے پہلے — نازل کی گئی — اور بے شک — ہم — ان — کی — پڑھائی سے — غافل — رہے — یعنی اب یہ بہانہ نہیں چلے گا کہ تمہیں دستیاب نہ تھی۔
۳۔ عملی سبق: قرآن — اب بھی تمہارے پاس ہے؛ بہانے چھوڑو؛ عمل کرو۔"""
),
946: (
"یا تم یہ کہو — اگر ہم پر کتاب اتاری جاتی تو ہم ان سے — زیادہ ہدایت یافتہ — ہوتے — پس — بے شک — تمہارے پاس — تمہارے رب کی طرف سے — واضح دلیل — اور ہدایت اور رحمت — آ گئی — پس — اس سے زیادہ ظالم کون ہے جو اللہ کی آیات کو جھٹلائے اور ان سے — روکے — عنقریب — ہم — ان — لوگوں کو جو ہماری آیات سے روکیں گے — برا عذاب — دیں گے — اس وجہ سے جو وہ — روکیں گے",
"""۱۔ حجت — قرآن کی صورت میں مکمل۔
۲۔ ’’أَوْ تَقُولُوا لَوْ أَنَّا أُنزِلَ عَلَيْنَا الْكِتَابُ لَكُنَّا أَهْدَىٰ مِنْهُمْ‘‘ — یا تم یہ کہو — اگر ہم پر کتاب اتاری جاتی تو ہم ان سے — زیادہ ہدایت یافتہ — ہوتے — یعنی قرآن آ چکا؛ یہ بہانہ ختم۔
۳۔ ’’فَقَدْ جَاءَكُم بَيِّنَۃٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَۃٌ‘‘ — پس — بے شک — تمہارے پاس — تمہارے رب کی طرف سے — واضح دلیل — اور ہدایت اور رحمت — آ گئی۔
۴۔ ’’فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِآيَاتِ اللّٰہِ وَصَدَفَ عَنْهَا سَنَجْزِي الَّذِينَ يَصْدِفُونَ عَنْ آيَاتِنَا سُوءَ الْعَذَابِ بِمَا كَانُوا يَصْدِفُونَ‘‘ — پس — اس سے زیادہ ظالم کون ہے جو اللہ کی آیات کو جھٹلائے اور ان سے — روکے — عنقریب — ہم — ان — لوگوں کو جو ہماری آیات سے روکیں گے — برا عذاب — دیں گے — اس وجہ سے جو وہ — روکیں گے — یعنی آیات کی تکذیب اور رُکنا — دونوں ظلم ہیں۔
۵۔ عملی سبق: قرآن کو اپنا قائد بناؤ؛ دوسروں کو بھی قرآن سے رُکنا مت سکھاؤ۔"""
),
947: (
"کیا وہ — سوائے اس کے کہ — ان — کے پاس — فرشتے آئیں — یا تمہارا رب آئے — یا تمہارے رب کی نشانیوں میں سے کچھ آ جائے — انتظار کر رہے ہیں — جس دن — تمہارے رب کی نشانیوں میں سے کچھ آجائیں گے — اس — نفس — کو — جو اس سے پہلے ایمان نہیں لایا — یا اپنے ایمان میں نیکی نہیں کمائی — اس — کا ایمان — فائدہ — نہیں دے گا — کہہ دیں: انتظار — کرو — ہم — بھی — انتظار — کرتے ہیں",
"""۱۔ معجزہ کا انتظار — بے فائدہ۔
۲۔ ’’هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَۃُ أَوْ يَأْتِيَ رَبُّكَ أَوْ يَأْتِيَ بَعْضُ آيَاتِ رَبِّكَ‘‘ — کیا وہ — سوائے اس کے کہ — ان — کے پاس — فرشتے آئیں — یا تمہارا رب آئے — یا تمہارے رب کی نشانیوں میں سے کچھ آ جائے — انتظار کر رہے ہیں — یعنی معجزات کا انتظار رکھنا۔
۳۔ ’’يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا‘‘ — جس دن — تمہارے رب کی نشانیوں میں سے کچھ آجائیں گے — اس — نفس — کو — جو اس سے پہلے ایمان نہیں لایا — یا اپنے ایمان میں نیکی نہیں کمائی — اس — کا ایمان — فائدہ — نہیں دے گا — یعنی آخری نشانی کے بعد ایمان — قبول نہیں ہوگا۔
۴۔ ’’قُلِ انتَظِرُوا إِنَّا مُنتَظِرُونَ‘‘ — کہہ دیں: انتظار — کرو — ہم — بھی — انتظار — کرتے ہیں۔
۵۔ عملی سبق: بروقت ایمان لاؤ؛ آخری نشانی کا انتظار بے فائدہ ہے۔"""
),
948: (
"بے شک — جنہوں نے اپنا — دین — تقسیم — کر لیا اور گروہوں میں بٹ گئے — آپ — کا — ان — سے — کوئی — سروکار نہیں — بے شک — ان — کا معاملہ — اللہ — پر ہے — پھر وہ — انہیں — بتا — دے گا — جو — وہ — کرتے تھے",
"""۱۔ دین کی تقسیم — اللہ کے سپرد۔
۲۔ ’’إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا لَّسْتَ مِنْهُمْ فِي شَيْءٍ‘‘ — بے شک — جنہوں نے اپنا — دین — تقسیم — کر لیا اور گروہوں میں بٹ گئے — آپ — کا — ان — سے — کوئی — سروکار نہیں — یعنی دین میں فرقہ بندی — گناہ ہے۔
۳۔ ’’إِنَّمَا أَمْرُهُمْ إِلَى اللّٰہِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا يَفْعَلُونَ‘‘ — بے شک — ان — کا معاملہ — اللہ — پر ہے — پھر وہ — انہیں — بتا — دے گا — جو — وہ — کرتے تھے — یعنی فرقہ بندی کا حساب — اللہ لے گا۔
۴۔ عملی سبق: دین میں تقسیم مت کرو؛ صرف اللہ کی یکجہتی — اصل ہے۔"""
),
949: (
"جو — کوئی ایک نیکی لائے — اس — کے لیے — اس — کے دس — برابر — ہیں — اور جو ایک گناہ لائے — اسے — صرف — اسی — کے برابر — کا معاملہ دیا جائے گا — اور — ان — پر ظلم — نہیں کیا جائے گا",
"""۱۔ نیکی کا بدلہ — دس گنا۔
۲۔ ’’مَن جَاءَ بِالْحَسَنَۃِ فَلَهُ عَشْرُ أَمْثَالِهَا وَمَن جَاءَ بِالسَّيِّئَۃِ فَلَا يُجْزَىٰ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ‘‘ — جو — کوئی ایک نیکی لائے — اس — کے لیے — اس — کے دس — برابر — ہیں — اور جو ایک گناہ لائے — اسے — صرف — اسی — کے برابر — کا معاملہ دیا جائے گا — اور — ان — پر ظلم — نہیں کیا جائے گا — یعنی نیکی — دس گنا — گناہ — برابر — اللہ کامل عدل کرتا ہے۔
۳۔ عملی سبق: نیکی کرو — دس گنا اجر ہے؛ گناہ سے بچو؛ اللہ کا عدل کامل ہے۔"""
),
950: (
"کہہ دیں: بے شک — مجھے — میرے رب — نے — سیدھے — راستے — کی ہدایت دی — سیدھا — دین — ابراہیمؑ کا مذہب — یکسو ہو کر — اور وہ مشرکوں میں سے — نہ تھے",
"""۱۔ نبی ﷺ کی راہ — ابراہیمؑ کا دین۔
۲۔ ’’قُلْ إِنَّنِي هَدَانِي رَبِّي إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّۃَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ‘‘ — کہہ دیں: بے شک — مجھے — میرے رب — نے — سیدھے — راستے — کی ہدایت دی — سیدھا — دین — ابراہیمؑ کا مذہب — یکسو ہو کر — اور وہ مشرکوں میں سے — نہ تھے — یعنی نبی ﷺ کی راہ — ابراہیمؑ کی طرح — یکسوئی — اور — شرک سے برات — ہے۔
۳۔ عملی سبق: توحید — ابراہیمؑ کی راہ اپناؤ؛ شرک سے برات۔"""
),
951: (
"کہہ دیں: بے شک میری نماز، میری قربانی، میری زندگی اور میری موت — اللہ کے لیے — سب جہانوں کے رب — کے لیے ہیں",
"""۱۔ سب کچھ — اللہ کے لیے۔
۲۔ ’’قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلّٰہِ رَبِّ الْعَالَمِينَ‘‘ — کہہ دیں: بے شک میری نماز، میری قربانی، میری زندگی اور میری موت — اللہ کے لیے — سب جہانوں کے رب — کے لیے ہیں — یعنی نبی ﷺ اپنی زندگی اور موت — سب — اللہ کے لیے کرتے ہیں۔
۳۔ عملی سبق: اپنی زندگی اور موت — اللہ کے لیے مخصوص کرو۔"""
),
952: (
"اس کے لیے کوئی شریک نہیں — اور — اسی — کا مجھے حکم دیا گیا ہے — اور — میں — سب سے پہلا — مسلمانوں میں سے ہوں",
"""۱۔ اللہ — بے شریک — اور نبی ﷺ — سب سے پہلے مسلمان۔
۲۔ ’’لَا شَرِيكَ لَهُ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ‘‘ — اس کے لیے کوئی شریک نہیں — اور — اسی — کا مجھے حکم دیا گیا ہے — اور — میں — سب سے پہلا — مسلمانوں میں سے ہوں — یعنی توحید — نبی ﷺ کا حکم — اور آپ — سب سے پہلے — مسلمان — ہیں۔
۳۔ عملی سبق: توحید اپناؤ؛ اللہ کے بغیر کسی کی عبادت مت کرو۔"""
),
953: (
"کہہ دیں: کیا میں اللہ کے سوا — کوئی اور — رب — تلاش کروں — حالانکہ وہ — ہر چیز کا رب ہے — اور کوئی نفس — صرف — اپنے اوپر — کا بوجھ اٹھاتا ہے — اور کوئی بوجھ اٹھانے والا — کسی اور کا بوجھ — نہیں اٹھائے گا — پھر — تمہاری — واپسی — تمہارے — رب — کے پاس — ہوگی — پھر وہ — تمہیں بتا دے گا — جو — تم — اختلاف — کرتے تھے",
"""۱۔ ہر نفس — اپنے بار کا ذمہ دار۔
۲۔ ’’قُلْ أَغَيْرَ اللّٰہِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ‘‘ — کہہ دیں: کیا میں اللہ کے سوا — کوئی اور — رب — تلاش کروں — حالانکہ وہ — ہر چیز کا رب ہے — یعنی اللہ کے سوا — کسی اور کا — کوئی — رب نہیں ہو سکتا۔
۳۔ ’’وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَۃٌ وِزْرَ أُخْرَىٰ‘‘ — اور کوئی نفس — صرف — اپنے اوپر — کا بوجھ اٹھاتا ہے — اور کوئی بوجھ اٹھانے والا — کسی اور کا بوجھ — نہیں اٹھائے گا — یعنی اپنا عمل — اپنی — ذمہ داری ہے۔
۴۔ ’’ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ‘‘ — پھر — تمہاری — واپسی — تمہارے — رب — کے پاس — ہوگی — پھر وہ — تمہیں بتا دے گا — جو — تم — اختلاف — کرتے تھے — یعنی قیامت میں — ہر اختلاف کا فیصلہ — اللہ کرے گا۔
۵۔ عملی سبق: غلط فہمی میں — دوسروں — کا بوجھ — مت اٹھاؤ؛ ہر — ایک اپنے عمل کا ذمہ دار ہے۔"""
),
954: (
"اور وہی — ہے جس نے — تمہیں — زمین کا جانشین بنایا — اور اس نے — تم میں سے بعض کو بعض — پر — درجات میں — بلند کیا — تاکہ — تمہیں — آزمائے — اس میں جو اس نے تمہیں دیا — بے شک تمہارا رب — جلدی حساب دینے والا ہے — اور بے شک وہ — بخشش والا — مہربان ہے",
"""۱۔ تمہاری — زمین پر — خلافت — اللہ کا امتحان ہے۔
۲۔ ’’وَهُوَ الَّذِي جَعَلَكُمْ خَلَائِفَ الْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ لِّيَبْلُوَكُمْ فِي مَا آتَاكُمْ‘‘ — اور وہی — ہے جس نے — تمہیں — زمین کا جانشین بنایا — اور اس نے — تم میں سے بعض کو بعض — پر — درجات میں — بلند کیا — تاکہ — تمہیں — آزمائے — اس میں جو اس نے تمہیں دیا — یعنی تمہیں جو کچھ دیا گیا — وہ آزمائش ہے۔
۳۔ ’’إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ‘‘ — بے شک تمہارا رب — جلدی حساب دینے والا ہے — اور بے شک وہ — بخشش والا — مہربان ہے — یعنی اللہ جلدی حساب بھی لیتا ہے اور بخش بھی دیتا ہے۔
۴۔ عملی سبق: جو کچھ دیا گیا — اللہ کی — آزمائش ہے؛ شکر ادا کرو؛ بروقت عمل کرو۔"""
),
}
